package schemadoc

import (
	"bytes"
	"fmt"
	"strings"
)

// Document is one schema of the reference page.
type Document struct {
	// Title is the heading of the section.
	Title string
	// Intro is the Markdown text between the heading and the table.
	Intro string
	// Reload returns the reload cell of a key path. A document without it has no Reload column.
	Reload func(path string) string
	// Schema is the JSON Schema.
	Schema []byte
}

// Header is the head of the generated page.
const Header = `# Schema reference

<!-- Generated by cmd/jsonschema-generator from .schema/*.json. Do not edit; run ` + "`task docs-schema`" + `. -->

This page is generated from the JSON Schemas of the repository. A test fails when it is not up to date.
Types ` + "`duration`" + `, ` + "`size`" + ` and ` + "`secret`" + ` are strings or references with their own format, see
the [bootstrap file](../relay-proxy/bootstrap-config.md). The meaning of each bootstrap key is on that page.
`

// Render writes the Markdown reference of the documents.
func Render(documents []Document) ([]byte, error) {
	var out bytes.Buffer

	out.WriteString(Header)

	for _, doc := range documents {
		keys, err := Keys(doc.Schema)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", doc.Title, err)
		}

		fmt.Fprintf(&out, "\n## %s\n\n", doc.Title)

		if doc.Intro != "" {
			out.WriteString(doc.Intro + "\n\n")
		}

		reloadHead, reloadRule := "", ""
		if doc.Reload != nil {
			reloadHead, reloadRule = " Reload |", "---|"
		}

		out.WriteString(
			"| Key | Type | Required | Default |" + reloadHead + " Allowed | Description |\n|---|---|---|---|" +
				reloadRule + "---|---|\n",
		)

		for i := range keys {
			key := &keys[i]

			reload := ""
			if doc.Reload != nil {
				reload = " " + doc.Reload(key.Path) + " |"
			}

			fmt.Fprintf(&out, "| `%s` | %s | %s | %s |%s %s | %s |\n", key.Path, cell(key.Type), required(key),
				code(key.Default), reload, cell(key.Allowed), describe(key))
		}
	}

	return out.Bytes(), nil
}

func required(key *Key) string {
	switch {
	case key.Required:
		return "yes"
	case len(key.RequiredFor) > 0:
		return "for " + names(key.RequiredFor)
	default:
		return ""
	}
}

func describe(key *Key) string {
	text := cell(key.Description)

	if len(key.OnlyFor) > 0 {
		if text != "" {
			text += " "
		}

		text += "Only for " + names(key.OnlyFor) + "."
	}

	return text
}

func names(values []string) string {
	quoted := make([]string, len(values))
	for i, value := range values {
		quoted[i] = "`" + value + "`"
	}

	return strings.Join(quoted, ", ")
}

func code(text string) string {
	if text == "" {
		return ""
	}

	return "`" + cell(text) + "`"
}

// cell makes a text safe for a table cell.
func cell(text string) string {
	text = strings.Join(strings.Fields(text), " ")

	return strings.ReplaceAll(text, "|", "\\|")
}
